type Page = "generate" | "favorites" | "voices" | "settings" | "license";
type ServiceState = "ready" | "processing" | "warning" | "error";

type PortablePaths = { root: string; data: string; voices: string; favorites: string; history: string; temp: string; models: string; logs: string };
type ComponentStatus = { id: string; label: string; installed: boolean; required: boolean; detail: string };
type EnvironmentInfo = { windows: string; architecture: string; cpu: string; gpu: string; cudaAvailable: boolean; python: string; uv: string; ffmpeg: string; freeSpaceGb: number | null; writable: boolean; irodoriRoot: string; serverRoot: string; components?: ComponentStatus[] };
type AppState = { setupRequired: boolean; noticeVersion: string; noticeAcknowledgedAt: string | null; paths: PortablePaths; environment: EnvironmentInfo };
type TtsConfig = { serverRoot: string; irodoriRoot: string; pythonPath: string; voicesDir: string; portableRoot?: string; serverUrl: string; port: number; apiKey: string; model: string; modelRevision: string; defaultVoice: string; speed: number; numSteps: number; cfgScaleText: number; cfgScaleSpeaker: number; seed: number | null; modelPrecision: string; codecPrecision: string; modelDevice: string; codecDevice: string; schedule: string; swayCoefficient: number; autoStart: boolean; stopOnExit: boolean };
type TtsStatus = { healthy: boolean; running: boolean; ownedByStudio: boolean; pid: number | null; port: number; modelLoaded: boolean; message: string };
type Voice = { id: string; name: string; iconPath: string | null; iconDataUrl?: string | null; caption: string; voiceDesign: string; references: string[]; updatedAt: string };
type VoiceDraft = Omit<Voice, "id" | "updatedAt"> & { id: string | null };
type EmojiTag = { emoji: string; name: string; description: string; supported: boolean };
type Segment = { id: string; text: string; tags: EmojiTag[] };
type Generation = { id: string; audioPath: string; audioBase64: string | null; text: string; voiceId: string | null; voiceName: string; emojis: EmojiTag[]; caption: string; seed: number | null; preset: string; model: string; modelRevision: string; createdAt: string; isFavorite: boolean; exists: boolean; durationSeconds: number | null };
type Notice = { kind: "error" | "warning" | "success"; title: string; body: string; detail?: string };
type HuggingFaceModel = { id: string; downloads: number | null; likes: number | null };
type ModelInstallProgress = { model: string; file: string; percent: number; downloadedBytes: number; totalBytes: number };
type ModelFamily = { id: string; label: string; normal: string; quantized: string; normalRevision: string; quantizedRevision: string };

